def classify_samples(R2):
    on = y > R2
    comps, i = [], 0
    while i < len(on):
        if on[i]:
            j = i
            while j < len(on) and on[j]:
                j += 1
            comps.append((i == 0, j == len(on)))
            i = j
        else:
            i += 1
    if len(comps) == 1 and comps[0] == (True, True):
        return "All"
    l_ = int(any(a for a, _ in comps)); u_ = int(any(b for _, b in comps)); k_ = sum(1 for a, b in comps if not a and not b)
    names = {(0, 0, 0): "Empty", (1, 0, 0): "lower ray", (0, 1, 0): "upper ray", (1, 1, 0): "two rays", (0, 0, 1): "window"}
    return names.get((l_, u_, k_), f"({l_},{u_},{k_})")


ylo, yhi = ax.get_ylim()
