ax.set_xscale("log"); ax.set_xlabel(r"precision $\Pi$"); ax.set_ylabel(r"$\sigma^2$")
ax.set_ylim(0, 1.7 * F)
ax.legend(loc="upper left", bbox_to_anchor=(1.01, 1.0), fontsize=7.5)
grid_(ax)
