# ---------------------------------------------------------------- 4. peak heights
xg = np.linspace(2.0005, 100, 600)


def peak_bayes(kap_):
    P0_ = 1.0 * lam / (kap_ * Sig)
    Gr = -lam + np.sqrt(lam**2 + lam * 1.0 - 2 * Sig * P0_)
    Pr = P0_ * Gr / (1.0 - Gr)
    return s2(Gr, Pr) / F


def peak_mis(x_):
    l1 = 1.0
    S1 = x_ * F * l1
    r = Sig / S1
    a2, b1, c0 = 1 + r, 4 * r * l1, 2 * lam * l1 - 4 * r * l1**2
    G = 2 * c0 / (b1 + np.sqrt(b1**2 + 4 * a2 * c0))
    Pr = (G**2 + 2 * l1 * G) / (2 * S1)
    return s2(G, Pr) / F


yb, ym = np.array([peak_bayes(k) for k in xg]), np.array([peak_mis(k) for k in xg])
fig, ax = plt.subplots(figsize=(6.6, 4.0), constrained_layout=True)
ax.plot(xg, yb, color=C1, label=r"Bayesian-weight gain, $x = \kappa$")
ax.plot(xg, ym, color=C2, ls="--", label=r"misspecified Kalman gain, $x = F'/F$")
ax.annotate(f"{ym[-1]:.3f}", (xg[-1], ym[-1]), xytext=(-4, 4), textcoords="offset points", ha="right", color=INK, fontsize=8)
ax.annotate(f"{yb[-1]:.4f}", (xg[-1], yb[-1]), xytext=(-4, 4), textcoords="offset points", ha="right", color=INK, fontsize=8)
ax.set_xlabel(r"initial over-weighting $x$ (window iff $x > 2$)"); ax.set_ylabel(r"peak $M/F$")
ax.legend(loc="upper left"); grid_(ax)
