ax = axs[0]
ax.plot(ts, post, color=C1, label="posterior")
ax.axhspan(0.09, Mx, color=C1, alpha=0.12, lw=0, label=rf"window band $R^2 \in (0.09, {Mx:.5f})$")
ax.axhline(F, color=MUTED, lw=0.8, ls=":"); ax.text(ts[-1], F * 1.3, r"$F$", color=MUTED, ha="right")
ax.axvline(100, color=C2, lw=1.0, ls="--", label=r"$\Delta t_E = 100$")
ax.set_xscale("log"); ax.set_xlabel(r"$\Delta t$"); ax.set_ylabel("error"); ax.set_title("D1, posterior: a window")
ax.legend(loc="upper right"); grid_(ax)
ax = axs[1]
ax.plot(ts, avg / F - 1, color=C3, label=r"averaged$/F - 1$")
ax.axhspan(mn / F - 1, 0, color=C3, alpha=0.25, lw=0, label=r"two-ray band $R^2 \in (\min, F)$")
ax.axhline(0, color=MUTED, lw=0.8, ls=":")
ax.axvline(100, color=C2, lw=1.0, ls="--", label=r"$\Delta t_E = 100$")
ax.set_xscale("log"); ax.set_yscale("symlog", linthresh=2e-4); ax.set_xlabel(r"$\Delta t$"); ax.set_ylabel(r"averaged$/F - 1$")
ax.set_title("D1, time average: two rays (dip of 0.125%)"); ax.legend(loc="upper right"); grid_(ax)
save(fig, "fig09_sampled_relay", f"""
Figure 9. Sampled relay D1 (gain 1 - exp(-G dt)) along the sampling interval (Propositions 28, 31, 36; Numerical result 37).
G = 0.5, lambda = 1, Sigma = 0.01, Pi = 1 (G > 2 F Pi, so the excess set is (0, dt_E) with dt_E = 100). Left: the error at
sample times rises from 0.09 to a single maximum {Mx:.5f} at dt = 2.4645 and falls to 0, a window for R^2 in (0.09, {Mx:.5f}).
Right: the time average, shown as avg/F - 1 on a symmetric-log axis, crosses F at dt_E, dips to {mn:.7f} (0.125% below F) at
dt = 200 and returns to F from below, giving two rays for R^2 between the minimum and F.""")

# ---------------------------------------------------------------- 10. Sigma sweep abs vs rel
from t12_common import sig_funcs  # noqa: E402
ps = {"lam": 1, "Pi": 1, "G": 1, "rho": 10}
us = np.logspace(-4, 4, 400)
fig, axs = plt.subplots(1, 2, figsize=(10, 3.8), constrained_layout=True)
for ax, conv, ttl in ((axs[0], "abs", r"absolute tolerance: $\sigma^2$ (every family monotone)"),
                      (axs[1], "rel", r"relative tolerance: $\sigma^2/F$ (windows return iff $\rho > 2$)")):
    for fam, col, ls, lab in (("B2", C1, "-", r"$\Sigma$-independent gain, $G = 1$"), ("B3", C2, "--", r"$\Sigma$-tracking, over-trust $\rho = 10$"),
                              ("B5", C3, "-.", "optimal")):
        f_, _, _ = sig_funcs(fam, conv, ps)
        ax.plot(us, [float(f_(mp.mpf(float(u)))) for u in us], color=col, ls=ls, label=lab)
    ax.set_xscale("log"); ax.set_yscale("log"); ax.set_xlabel(r"$\nu = 2\Sigma\Pi/\lambda^2$ ($\lambda = \Pi = 1$)")
    ax.set_title(ttl); ax.legend(loc="upper left" if conv == "abs" else "lower left"); grid_(ax)
axs[1].axhline(1, color=MUTED, lw=0.8, ls=":")
save(fig, "fig10_process_noise", """
Figure 10. The process-noise sweep on a moving floor F = Sigma/lambda (Lemma 39, Propositions 40-43). lambda = Pi = 1.
Left, absolute tolerance (fixed R^2): the Sigma-independent gain (G = 1), the Sigma-tracking gain over-trusting precision by
rho = 10, and the optimal filter are all increasing, so only All or an upper ray occur. Right, relative tolerance
(failure when sigma^2 > rF): the Sigma-independent gain decreases to 1/(1 + g), the optimal filter decreases as
2/(1 + sqrt(1 + u)), and the over-trusting gain rises above 1 to a peak of 2.17 before falling (a window for 1 < r < peak), which happens
exactly when rho > 2, Paper 1's factor of two.""")

